head.b:skin:
:root{color-scheme:light dark;--bg:#f6f7f4;--surface:#fff;--text:#203536;--muted:#536665;--line:#d9e1dc;--accent:#24684e;--tint:#eaf2eb;--hero:#1f3a3d;--hero-text:#f4faf5;--focus:#925011}
*{box-sizing:border-box}html{scroll-padding-top:24px}body{margin:0;background:var(--bg);color:var(--text);font-family:Pretendard,-apple-system,BlinkMacSystemFont,"Segoe UI","Malgun Gothic",sans-serif;font-size:16px;line-height:1.65;overflow-wrap:anywhere}a{color:var(--accent);text-underline-offset:4px}a:hover{text-decoration:underline}a:focus-visible,button:focus-visible,input:focus-visible,summary:focus-visible,[tabindex]:focus-visible{outline:3px solid var(--focus);outline-offset:4px}img,svg{max-width:100%;height:auto}button,input{font:inherit}button,summary{cursor:pointer}h1,h2,h3,p{margin-top:0}h1,h2,h3{line-height:1.35;letter-spacing:-.035em}h1{font-size:clamp(28px,3.2vw,42px)}h2{font-size:26px}h3{font-size:20px}[hidden]{display:none!important}.wrap{width:min(1200px,calc(100% - 64px));margin-inline:auto}.skip{position:absolute;left:16px;top:-100px;z-index:10;background:var(--surface);padding:12px}.skip:focus{top:12px}.site-header{background:var(--surface);border-bottom:1px solid var(--line)}.masthead{padding-block:25px 20px}.brand{display:inline-block;font-size:29px;line-height:1.2;font-weight:800;letter-spacing:-.06em;color:var(--text);text-decoration:none}.brand::before{content:'↗';display:inline-grid;place-items:center;width:34px;height:34px;margin-right:10px;background:var(--hero);color:var(--hero-text);border-radius:8px;font-size:24px}.tagline{margin:8px 0 0 45px;color:var(--muted);font-size:13px}.category-nav{display:flex;gap:6px;overflow-x:auto;white-space:nowrap;padding:0 0 13px;scrollbar-width:thin}.category-nav a{flex:0 0 auto;border-radius:6px;padding:8px 10px;text-decoration:none;color:var(--muted);font-size:13px;font-weight:600}.category-nav a:hover,.category-nav a[aria-current=page]{background:var(--tint);color:var(--accent)}.category-nav .num{margin-right:6px;font-size:11px}.hero{margin-top:32px;background:var(--hero);color:var(--hero-text);padding:36px 40px;border-radius:16px;position:relative;overflow:hidden}.hero::after{content:'';position:absolute;width:220px;height:220px;right:-30px;top:-70px;border:1px solid #6c9690;border-radius:50%;box-shadow:0 0 0 34px #ffffff08,0 0 0 68px #ffffff06;pointer-events:none}.eyebrow{font-size:12px;letter-spacing:.14em;font-weight:700;margin-bottom:12px}.hero h1{max-width:700px;margin-bottom:12px}.hero p:last-child{margin:0;position:relative;z-index:1}.study{margin-block:34px}.section-heading{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin-bottom:16px}.section-heading h2{margin:0;font-size:23px}.section-heading span{color:var(--muted);font-size:13px}.study-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.study-card{display:flex;flex-direction:column;padding:21px 20px 19px;background:var(--surface);border:1px solid var(--line);border-radius:10px;text-decoration:none;color:var(--text);transition:border-color .15s}.study-card:hover{border-color:var(--accent);text-decoration:none}.study-card .step{color:var(--accent);font-size:12px;font-weight:700;letter-spacing:.1em;margin-bottom:12px}.study-card strong{font-size:17px;letter-spacing:-.035em;margin-bottom:7px}.study-card p{font-size:14px;color:var(--muted);margin:0;line-height:1.65}.layout{display:grid;grid-template-columns:minmax(0,1fr) 248px;gap:40px;margin-block:36px 64px;align-items:start}.main-column,.sidebar,.widget{min-width:0}.post-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}.post-card{background:var(--surface);border:1px solid var(--line);border-radius:12px;overflow:hidden}.thumbnail{display:block;aspect-ratio:16/9;background:var(--tint);overflow:hidden}.thumbnail img{width:100%;height:100%;object-fit:cover;display:block}.thumb-fallback{display:grid;place-items:center;height:100%;color:var(--accent);font-size:22px;font-weight:700;letter-spacing:.06em;background:linear-gradient(135deg,transparent 49.5%,var(--line) 50%,transparent 50.5%),var(--tint);background-size:30px 30px}.card-copy{padding:22px}.badge,.chip{display:inline-block;color:var(--accent);background:var(--tint);border-radius:5px;font-size:12px;font-weight:600;padding:4px 9px;text-decoration:none}.post-card h2{font-size:21px;margin:13px 0 10px}.post-card h2 a{color:var(--text);text-decoration:none}.post-card h2 a:hover{text-decoration:underline}.excerpt{font-size:15px;color:var(--muted);line-height:1.75;margin-bottom:16px}.post-date{font-size:13px;color:var(--muted)}.sidebar .widget{padding:22px 0;border-bottom:1px solid var(--line)}.sidebar .widget:first-child{padding-top:0}.sidebar h2{font-size:17px;margin-bottom:14px}.sidebar p,.sidebar li{font-size:14px}.search-form{display:flex;gap:7px}.search-form input{width:100%;min-width:0;background:var(--surface);color:var(--text);border:1px solid var(--line);border-radius:6px;padding:9px}.search-form button{flex-shrink:0;border:0;border-radius:6px;background:var(--hero);color:var(--hero-text);padding:9px 12px;font-size:14px}.label-list,.archive-list{list-style:none;padding:0;margin:0}.label-list li,.archive-list li{margin:9px 0}.label-list a{display:flex;justify-content:space-between;gap:12px;text-decoration:none}.label-list span{color:var(--muted)}summary{font-weight:700}.archive-list{padding-top:10px}.category-intro{padding:28px 0 26px;border-bottom:1px solid var(--line)}.category-intro h1{margin-bottom:12px}.category-intro p{color:var(--muted);margin-bottom:16px}.pager{display:flex;flex-wrap:wrap;justify-content:space-between;gap:14px;margin-top:28px;padding-top:20px;border-top:1px solid var(--line);font-size:14px}.pager a{text-decoration:none}.category-intro .pager{margin:0;padding:0;border:0}.breadcrumbs{font-size:13px;display:flex;flex-wrap:wrap;gap:9px;margin-bottom:24px;color:var(--muted)}.article-header,.post-body,.article-footer{width:100%;max-width:740px;margin-inline:auto}.article-header{padding-bottom:28px;border-bottom:1px solid var(--line);margin-bottom:28px}.article-header h1{font-size:clamp(28px,3vw,38px);line-height:1.45;margin-bottom:18px}.post-body{font-size:18px;line-height:1.85}.post-body p{margin-bottom:1.35em}.post-body h2{font-size:27px;margin:2.1em 0 .8em}.post-body h3{font-size:22px;margin:1.8em 0 .75em}.post-body ul,.post-body ol{padding-left:1.4em;margin-block:1em 1.5em}.post-body li{margin:.5em 0}.post-body figure{margin:2em 0}.post-body figcaption{font-size:14px;line-height:1.7;color:var(--muted);margin-top:10px}.post-body img{height:auto;max-width:100%;border-radius:6px}.table-scroll{width:100%;overflow-x:auto;margin:1.5em 0;border:1px solid var(--line);border-radius:8px}.post-body table{width:100%;border-collapse:collapse;font-size:15px;line-height:1.7}.post-body th,.post-body td{padding:13px 15px;border-bottom:1px solid var(--line);text-align:left;min-width:110px}.post-body th{background:var(--tint);font-weight:700}.post-body blockquote{margin:1.8em 0;padding:18px 24px;background:var(--tint);border-left:3px solid var(--accent)}.post-body blockquote p:last-child{margin:0}.post-body small{font-size:14px;color:var(--muted);line-height:1.75}.post-body code{font-family:Consolas,monospace;font-size:.9em;background:var(--tint);padding:2px 5px;border-radius:4px}.post-body pre{max-width:100%;overflow-x:auto;background:var(--tint);padding:18px;border-radius:8px}.post-body pre code{padding:0}.article-footer{margin-top:32px}.chips{display:flex;flex-wrap:wrap;gap:8px}.related{margin-top:35px;padding:24px;border:1px solid var(--line);border-radius:10px;background:var(--surface)}.related h2{font-size:20px;margin-bottom:14px}.related ol{padding-left:22px;margin-bottom:0}.related li{padding:7px 0}.empty{padding:30px;border:1px solid var(--line);border-radius:10px;background:var(--surface)}.site-footer{border-top:1px solid var(--line);padding:28px 0 35px;color:var(--muted);font-size:13px}.site-footer p{margin-bottom:6px}.site-footer .widget{margin-top:8px}.preview-toolbar{background:var(--tint);border-bottom:1px solid var(--line);padding:10px 0;font-size:13px}.preview-toolbar .wrap{display:flex;flex-wrap:wrap;align-items:center;gap:12px}.preview-toolbar button{background:var(--surface);color:var(--accent);border:1px solid var(--line);padding:5px 12px;border-radius:5px}.preview-toolbar button[aria-pressed=true]{background:var(--hero);color:var(--hero-text)}
@media(min-width:761px){.category-nav{justify-content:space-between;gap:0}.category-nav a{padding-inline:7px}}
@media(max-width:1000px){.study-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.layout{grid-template-columns:minmax(0,1fr) 220px;gap:28px}.post-grid{grid-template-columns:1fr}}
@media(max-width:760px){.wrap{width:calc(100% - 32px)}.masthead{padding-block:20px 15px}.tagline{margin-left:0}.hero{padding:28px 24px;margin-top:20px}.hero h1{font-size:29px}.hero::after{opacity:.4}.study{margin-block:26px}.study-grid{gap:10px}.study-card{padding:17px 15px}.study-card strong{font-size:16px}.study-card p{font-size:13px}.section-heading span{font-size:12px}.layout{grid-template-columns:minmax(0,1fr);margin-top:28px;gap:40px}.sidebar{border-top:1px solid var(--line);padding-top:24px}.post-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.post-body{font-size:17px}.post-body h2{font-size:24px}.category-intro{padding-top:10px}.article-header h1{font-size:28px}.post-body blockquote{padding:15px 18px}.card-copy{padding:18px}.post-card h2{font-size:20px}}
@media(max-width:520px){.post-grid{grid-template-columns:1fr}.section-heading{align-items:center}.hero h1{font-size:27px}.study-card .step{margin-bottom:8px}.category-intro h1{font-size:28px}}
@media(prefers-color-scheme:dark){:root{--bg:#121d20;--surface:#19272a;--text:#e4ede8;--muted:#b0c1ba;--line:#384c48;--accent:#95d4ad;--tint:#253c33;--hero:#223f43;--hero-text:#f4faf5;--focus:#f5bb78}.post-body img{background:#fff}}
@media(prefers-reduced-motion:reduce){*{transition:none!important}}
@media print{.site-header,.sidebar,.site-footer,.preview-toolbar,.related,.pager,.study{display:none}.layout{display:block}.wrap{width:100%}body{background:white;color:black}.post-body{font-size:12pt}.article-header h1{font-size:22pt}}

body.script:
(() => {
  'use strict';
  document.querySelectorAll('.post-body table').forEach(table => {
    if (table.parentElement.classList.contains('table-scroll')) return;
    const wrapper = document.createElement('div');
    wrapper.className = 'table-scroll';
    wrapper.tabIndex = 0;
    wrapper.setAttribute('role', 'region');
    wrapper.setAttribute('aria-label', '표: 가로로 스크롤할 수 있습니다');
    table.before(wrapper);
    wrapper.append(table);
  });
  const box = document.querySelector('[data-related]');
  const category = document.querySelector('.breadcrumbs [data-category]');
  if (!box || !category || document.body.hasAttribute('data-preview')) return;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 8000);
  const label = category.dataset.category;
  const path = '/feeds/posts/summary/-/' + encodeURIComponent(label) + '?alt=json&max-results=6&orderby=published';
  const normalize = value => { const url = new URL(value, location.href); return url.pathname.replace(/\/$/, ''); };
  fetch(path, {signal: controller.signal, credentials: 'same-origin'})
    .then(response => { if (!response.ok) throw new Error('Feed unavailable'); return response.json(); })
    .then(data => {
      const list = box.querySelector('ol');
      for (const entry of data.feed.entry || []) {
        const alternate = (entry.link || []).find(link => link.rel === 'alternate');
        if (!alternate || !entry.title || normalize(alternate.href) === normalize(location.href)) continue;
        const url = new URL(alternate.href, location.href);
        if (!['https:', 'http:'].includes(url.protocol) || url.hostname !== location.hostname) continue;
        const item = document.createElement('li');
        const link = document.createElement('a');
        link.href = url.href;
        link.textContent = entry.title.$t;
        item.append(link);
        list.append(item);
        if (list.children.length === 5) break;
      }
      box.hidden = list.children.length === 0;
    })
    .catch(() => { box.hidden = true; })
    .finally(() => clearTimeout(timeout));
})();
